using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
[InitializeOnLoad] public static class SharkDolphinLiveCheck {
 const string Key="Underwater.SharkDolphinLive";
 class Sample {public SeaLife actor;public Animation player;public SkinnedMeshRenderer skin;public Vector3[] first;public Vector3 start;public float deformation,firstTime;}
 static Sample[] samples;static double began,nextCapture;static int phase,images;static Camera camera;static bool failed;static Vector3 cameraAnchor;
 static SharkDolphinLiveCheck(){EditorApplication.update+=Tick;}
 public static void Run(){SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");EditorApplication.EnterPlaymode();}
 static Vector3[] Points(SkinnedMeshRenderer skin){var mesh=new Mesh();skin.BakeMesh(mesh);var result=mesh.vertices;UnityEngine.Object.DestroyImmediate(mesh);return result;}
 static void Tick(){if(!SessionState.GetBool(Key,false))return;if(!EditorApplication.isPlaying){if(samples!=null){SessionState.SetBool(Key,false);EditorApplication.Exit(failed?1:0);}return;}if(Time.timeSinceLevelLoad<2)return;
 try{if(samples==null){var diver=Diver.Instance;typeof(Diver).GetField("menu",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(diver,false);samples=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(a=>a.kind=="Dolphin"||a.kind=="Reef shark").Select(a=>new Sample{actor=a,player=a.GetComponentInChildren<Animation>(),skin=a.GetComponentsInChildren<SkinnedMeshRenderer>().First(s=>s.enabled),start=a.transform.position}).ToArray();if(samples.Length!=4)throw new Exception("Missing shark/dolphin");foreach(var s in samples){s.first=Points(s.skin);s.firstTime=s.player[s.player.clip.name].time;}camera=new GameObject("Swim review camera").AddComponent<Camera>();camera.enabled=false;camera.CopyFrom(Camera.main);camera.enabled=false;camera.targetTexture=new RenderTexture(800,500,24);camera.fieldOfView=50;camera.nearClipPlane=.05f;camera.farClipPlane=150;RenderSettings.fog=false;RenderSettings.ambientLight=new Color(.45f,.55f,.6f);var lamp=new GameObject("Swim review light").AddComponent<Light>();lamp.type=LightType.Directional;lamp.intensity=.8f;lamp.transform.rotation=Quaternion.Euler(30,-40,0);began=EditorApplication.timeSinceStartup;Directory.CreateDirectory("Renders/SharkDolphinReview/Live");}
 foreach(var s in samples){var p=Points(s.skin);for(int i=0;i<p.Length;i++)s.deformation=Mathf.Max(s.deformation,Vector3.Distance(s.first[i],p[i]));}
 if(EditorApplication.timeSinceStartup>=nextCapture&&images<60){nextCapture=EditorApplication.timeSinceStartup+.18;var subject=images<30?samples.Single(s=>s.actor.kind=="Reef shark"):samples.Where(s=>s.actor.kind=="Dolphin").OrderBy(s=>s.actor.name).First();int frame=images%30;string kind=images<30?"Shark":"Dolphin";if(frame==0)cameraAnchor=subject.actor.transform.position+subject.actor.transform.right*6+Vector3.up*1.3f+subject.actor.transform.forward*.6f;camera.transform.position=cameraAnchor;camera.transform.LookAt(subject.skin.bounds.center);camera.Render();var previous=RenderTexture.active;RenderTexture.active=camera.targetTexture;var picture=new Texture2D(800,500,TextureFormat.RGB24,false);picture.ReadPixels(new Rect(0,0,800,500),0,0);picture.Apply();File.WriteAllBytes("Renders/SharkDolphinReview/Live/"+kind+"_"+frame.ToString("D2")+".png",picture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(picture);RenderTexture.active=previous;images++;}
 if(images<60||EditorApplication.timeSinceStartup-began<14)return;var lines=samples.Select(s=>s.actor.name+" liveDeformation="+s.deformation+" travel="+Vector3.Distance(s.start,s.actor.transform.position)+" clipTimeDelta="+(s.player[s.player.clip.name].time-s.firstTime)+" rate="+s.player[s.player.clip.name].speed).ToArray();File.WriteAllLines("Renders/SharkDolphinReview/live-validation.txt",lines);foreach(var line in lines)Debug.Log("SWIM_LIVE "+line);foreach(var s in samples)if(s.deformation<.01f||Vector3.Distance(s.start,s.actor.transform.position)<.5f||s.player[s.player.clip.name].time-s.firstTime<2)throw new Exception("Live animation or travel stopped");Debug.Log("SHARK_DOLPHIN_LIVE_PASSED actualPlayback=true actualTravel=true");EditorApplication.ExitPlaymode();
 }catch(Exception e){failed=true;Debug.LogError(e);EditorApplication.ExitPlaymode();}}
}}
